using System;using Ossastra.CharacterCore;
class HealingTests{static int n;static void Check(bool ok,string name){if(!ok)throw new Exception(name);n++;}static void Main(){var method=typeof(Health).GetMethod("Heal");Check(method!=null,"missing controlled Heal");var a=new Health("a",200);var b=new Health("b",150);a.ApplyDamage(150);b.ApplyDamage(70);Check((int)method.Invoke(a,new object[]{100})==100&&a.Current==150,"absolute heal");Check((int)method.Invoke(b,new object[]{100})==70&&b.Current==150,"clamp maximum");a.ApplyDamage(1000);Check((int)method.Invoke(a,new object[]{100})==0&&a.Current==0,"no resurrection");var type=typeof(Health).Assembly.GetType("Ossastra.CharacterCore.HealingBottleState");Check(type!=null,"missing shared bottle authority");dynamic bottle=Activator.CreateInstance(type);Check(!bottle.TryUse(new[]{a,b})&&bottle.Count==1,"all living full reject");b.ApplyDamage(100);Check(bottle.TryUse(new[]{a,b})&&bottle.Count==0&&b.Current==150&&a.Current==0,"single living use");Check(!bottle.TryUse(new[]{a,b}),"empty reject");Check(bottle.TryRefill()&&bottle.Count==1,"first refill");b.ApplyDamage(20);Check(bottle.TryUse(new[]{b,b})&&bottle.UseCount==2,"dedup party");Check(!bottle.TryRefill()&&bottle.Count==0,"cannot farm campfire");Console.WriteLine(n+" healing contracts passed");}}
